      halted<D, C>(halt: Halt<D, C>, after: Interval): HaltSource<C>;
    };

    readonly policy: {
      model<M extends Model>(name: string, candidates: readonly M[], decide: (choice: ModelChoice) => NoInfer<M>): ModelPolicy;
