      at: TimeSpec,
      produce: (
        tick: { readonly now: Date; readonly units: readonly UnitView<T, S>[] },
        supply: Supplies<T, S>
      ) => readonly Supply<T, S>[]
    ): Supplier<T, S>;
    readonly operator: Supplier<never, never>;

    readonly ops: {
