  .amounts(e => [{ amount: 1, facets: [category.of(e.unit.attributes.category)] }]);

const drafterModel = H.policy.model('drafter-model', [sonnet, opus], ctx => {
  const month = { calendar: 'month' } as const;
  const audits = category.values.reduce((n, v) => n + ctx.metrics.total(auditsOpened, { facets: [category.of(v)], window: month }).total, 0);
  const paused = ctx.metrics.paused({ lane: conversationLane, window: month });
  return audits > 2 || paused.totalMs > 3_600_000 ? opus : sonnet;
});

const classifier = H.seat('classifier')
  .role(classifierRole)
  .model(haiku)
