const negotiating = H.role('negotiator')
  .input(z.object({ vendor: z.string(), item: z.string(), vendorMessage: z.string(), ourLastOffer: z.string() }))
  .output(z.object({ action: z.enum(['offer', 'accept', 'walkAway']), offer: z.string() }))
