const approvalByCategory = (metrics: Metrics) =>
  metrics.rateBy({
    among: { ...replyApproval.resolved(), resolver: 'human' },
    count: { ...replyApproval.resolved({ approved: true }), resolver: 'human' },
    by: category,
    days: 7,
