  'audit-on-approval-drop',
  H.on.metric(approvalByCategory, { trip: { below: 0.9 }, reset: { above: 0.95 }, minSamples: 50 }),
  (event, act) =>
    event.state === 'tripped'
      ? [
          act.create(audits, { category: event.group }, `audit-${event.group}`),
          act.remember(drafterExperience, {
