  window: { lastDays: 7 },
  minSamples: 50,
  enter: { below: 0.9 },
  exit: { above: 0.95 },
  per: category,
};

const approvalsFell = H.trigger('approvals-fell')
  .on(H.when.crossing(approvals, approvalBand, 'entered'))
