  .data(z.object({ file: z.string(), database: databaseSchema, sequence: z.string() }))
  .states(
    H.state('queued', 'pending'),
    H.state('held', 'waiting'),
    H.state('applied', 'terminal', 'success'),
    H.state('failed', 'terminal', 'failure')
  );

